// Generates the two icon bundles: src/components/Icon/iconBundle.ts and
// .storybook/storyIconBundle.ts.
//
// Iconify normally fetches icon data from api.iconify.design on first use.
// That's how consumers get any of the 200k+ icons by name without a build
// step, and it stays true for names we can't know about. But every Iconify
// name that appears in *this* repo is knowable at build time, so we resolve
// those ahead of time and register them with addCollection() — they render
// instantly, offline, and without a network round trip.
//
// The split exists because roughly a third of the names in src/ appear only in
// stories. Those went into dist/ui.js too, so every consumer downloaded icons
// that only the docs site ever draws. Story-only names now go to a second
// bundle that only .storybook/preview.ts imports: Storybook keeps rendering
// them offline, consumers stop paying for them.
//
// Run `pnpm icons:bundle` after adding or changing an Iconify name in src/,
// and commit the result. Needs network access; the build itself does not.
// `pnpm check:icons` (part of `verify` and CI) fails if you forget.

import { writeFile } from 'node:fs/promises'
import { relative } from 'node:path'

import { RUNTIME_BUNDLE, STORY_BUNDLE, root, scanIcons } from './icon-scan.mjs'

const fetchCollection = async (prefix, names) => {
  const url = `https://api.iconify.design/${prefix}.json?icons=${names.join(',')}`
  const response = await fetch(url)
  if (!response.ok) {
    throw new Error(`${prefix}: ${response.status} ${response.statusText}`)
  }
  const data = await response.json()
  // Unknown names fail the build, so a typo surfaces immediately rather than
  // silently falling back to a runtime API call.
  const missing = names.filter((name) => !data.icons?.[name])
  if (missing.length) {
    throw new Error(`${prefix}: unknown icons — ${missing.join(', ')}`)
  }
  return data
}

const fetchAll = async (names) => {
  const byPrefix = new Map()
  for (const name of names) {
    const [prefix, icon] = name.split(':')
    if (!byPrefix.has(prefix)) byPrefix.set(prefix, [])
    byPrefix.get(prefix).push(icon)
  }

  const collections = []
  for (const [prefix, icons] of [...byPrefix].sort()) {
    console.log(`  ${prefix}: ${icons.sort().join(', ')}`)
    collections.push(await fetchCollection(prefix, icons.sort()))
  }
  return collections
}

const write = async (file, header, collections) => {
  const contents = `// GENERATED by scripts/build-icon-bundle.mjs — do not edit by hand.
//
${header}
//
// Regenerate with \`pnpm icons:bundle\`.
import { addCollection } from '@iconify/vue'

const collections = ${JSON.stringify(collections, null, 2)}

collections.forEach((collection) => addCollection(collection as any))
`
  await writeFile(file, contents)
}

const { runtime, story } = await scanIcons()
if (!runtime.size) {
  console.error('No Iconify names found in src/ — nothing to bundle.')
  process.exit(1)
}

console.log(`Shipped icons (${runtime.size}):`)
const runtimeCollections = await fetchAll([...runtime.keys()])
await write(
  RUNTIME_BUNDLE,
  `// Iconify data for every icon the library itself renders, so they appear
// without a call to api.iconify.design. Icon names supplied by consumers are
// not in here and still resolve through the API at runtime.`,
  runtimeCollections
)

console.log(`\nStory-only icons (${story.size}):`)
const storyCollections = story.size ? await fetchAll([...story.keys()]) : []
await write(
  STORY_BUNDLE,
  `// Iconify data for icons that appear only in stories and fixtures. Imported
// by .storybook/preview.ts alone, never by the library, so these never reach
// dist/ — they exist so Storybook renders offline without the API.`,
  storyCollections
)

console.log(
  `\nWrote ${relative(root, RUNTIME_BUNDLE)} (${runtime.size} icons)` +
    `\n      ${relative(root, STORY_BUNDLE)} (${story.size} icons)`
)
